/**
 * Create flink vector by hive vector from constant.
 */
public static ColumnVector createFlinkVectorFromConstant(LogicalType type, Object value, int batchSize) {
    return // PATH: Test should invoke the next AbstractOrcColumnVector.createHiveVectorFromConstant(...) [step in execution path]
    createFlinkVector(createHiveVectorFromConstant(type, value, batchSize), type);
}

/**
 * Create a orc vector from partition spec value. See hive {@code VectorizedRowBatchCtx#addPartitionColsToBatch}.
 */
private static ColumnVector createHiveVectorFromConstant(LogicalType type, Object value, int batchSize) {
    switch (type.getTypeRoot()) {
        case CHAR :
        case VARCHAR :
        case BINARY :
        case VARBINARY :
            return createBytesVector(batchSize, value);
        case BOOLEAN :
            return createLongVector(batchSize, ((Boolean) (value)) ? 1 : 0);
        case TINYINT :
        case SMALLINT :
        case INTEGER :
        case BIGINT :
            return createLongVector(batchSize, value);
        case DECIMAL :
            DecimalType decimalType = ((DecimalType) (type));
            // PATH: Test should invoke the next AbstractOrcColumnVector.createDecimalVector(...) [step in execution path]
            return createDecimalVector(batchSize, decimalType.getPrecision(), decimalType.getScale(), value);
        case FLOAT :
        case DOUBLE :
            return createDoubleVector(batchSize, value);
        case DATE :
            if (value instanceof LocalDate) {
                value = Date.valueOf(((LocalDate) (value)));
            }
            return createLongVector(batchSize, toInternal(((Date) (value))));
        case TIMESTAMP_WITHOUT_TIME_ZONE :
            return TimestampUtil.createVectorFromConstant(batchSize, value);
        default :
            throw new UnsupportedOperationException("Unsupported type: " + type);
    }
}

private static DecimalColumnVector createDecimalVector(int batchSize, int precision, int scale, Object value) {
    DecimalColumnVector dv = new DecimalColumnVector(batchSize, precision, scale);
    if (value == null) {
        dv.noNulls = false;
        dv.isNull[0] = true;
        dv.isRepeating = true;
    } else // PATH: Test should invoke the next DecimalColumnVector.set(...) [step in execution path]
    {
        dv.set(0, value instanceof HiveDecimal ? ((HiveDecimal) (value)) : HiveDecimal.create(((BigDecimal) (value))));
        dv.isRepeating = true;
        dv.isNull[0] = false;
    }
    return dv;
}

